    // Projection steps for lerp_r3_segment_error, the joints and t the unknowns (dimension + 1). Input: the first
    // 3 * (dimension + 1) + 3 outputs of the error kernel (J, then err), and for the bounded variant then
    // lower - x and upper - x ((dimension + 1) entries each, x the joints followed by t: the joints' limits minus q, and
    // for t the kernel's two last outputs). Output: the gradient (dimension + 1 entries), applied as x <- x - gradient.
    template <std::size_t rake, typename InputVector, typename OutputVector>
    static inline auto solve_lerp_r3_segment_error_lm_inner(const InputVector &x, OutputVector &y) noexcept
    {
        std::array<FloatVector<rake, 1>, 8> v;

           v[0] = sqrt(1e-06 + x[0] * x[0] + x[1] * x[1] + x[2] * x[2] + x[3] * x[3] + x[4] * x[4] + x[5] * x[5] + x[6] * x[6] + x[7] * x[7]);
   v[1] = (x[16] * x[0] + x[17] * x[1] + x[18] * x[2] + x[19] * x[3] + x[20] * x[4] + x[21] * x[5] + x[22] * x[6] + x[23] * x[7]) / v[0];
   v[2] = x[24] / v[0];
   v[3] = (x[8] * x[0] + x[9] * x[1] + x[10] * x[2] + x[11] * x[3] + x[12] * x[4] + x[13] * x[5] + x[14] * x[6] + x[15] * x[7]) / v[0];
   v[4] = sqrt(1e-06 + x[8] * x[8] + x[9] * x[9] + x[10] * x[10] + x[11] * x[11] + x[12] * x[12] + x[13] * x[13] + x[14] * x[14] + x[15] * x[15] - v[3] * v[3]);
   v[5] = (x[16] * x[8] + x[17] * x[9] + x[18] * x[10] + x[19] * x[11] + x[20] * x[12] + x[21] * x[13] + x[22] * x[14] + x[23] * x[15] - v[1] * v[3]) / v[4];
   v[6] = (x[25] - v[3] * v[2]) / v[4];
   v[7] = sqrt(1e-06 + x[16] * x[16] + x[17] * x[17] + x[18] * x[18] + x[19] * x[19] + x[20] * x[20] + x[21] * x[21] + x[22] * x[22] + x[23] * x[23] - v[1] * v[1] - v[5] * v[5]);
   v[7] = ((x[26] - v[1] * v[2] - v[5] * v[6]) / v[7]) / v[7];
   v[6] = (v[6] - v[5] * v[7]) / v[4];
   v[3] = (v[2] - v[3] * v[6] - v[1] * v[7]) / v[0];
   y[0] = x[16] * v[7] + x[8] * v[6] + x[0] * v[3];
   y[1] = x[17] * v[7] + x[9] * v[6] + x[1] * v[3];
   y[2] = x[18] * v[7] + x[10] * v[6] + x[2] * v[3];
   y[3] = x[19] * v[7] + x[11] * v[6] + x[3] * v[3];
   y[4] = x[20] * v[7] + x[12] * v[6] + x[4] * v[3];
   y[5] = x[21] * v[7] + x[13] * v[6] + x[5] * v[3];
   y[6] = x[22] * v[7] + x[14] * v[6] + x[6] * v[3];
   y[7] = x[23] * v[7] + x[15] * v[6] + x[7] * v[3];

    }

